/* Saved learning plans and owner-controlled production setup. */
(()=>{'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),icon=(n,s=20)=>window.AcademyShell.icon(n,s),link=(text,route,primary=false)=>`<a class="btn ${primary?'primary':''}" href="#${route}">${esc(text)} ${icon('Arrow',16)}</a>`,date=v=>v?new Date(v).toLocaleString():'';
let ctx=null,launch=null,savedPlan=null;
const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const labels={learning_plan_saved:'Weekly learning plan saved',account_access_activated:'Appointed access activated',account_appointment_saved:'Team appointment recorded',account_appointment_revoked:'Team appointment withdrawn',merchant_connection_verified:'Merchant connection verified',business_details_saved:'Business details saved',course_offers_saved:'Course offers saved',payment_confirmed:'Payment confirmed',recipe_saved:'Project draft saved',notebook_saved:'Notebook saved',recipe_submitted:'Project submitted for assessment',recipe_assign:'Project assigned to assessors',recipe_review:'Project reviewed',recipe_verify:'Project verified',pathway_certificate_issued:'Certificate issued',class_book:'Class booked',class_cancel:'Class booking cancelled',class_preferences:'Class preferences saved',class_assign:'Teacher assigned',class_slot:'Class time offered',class_meeting:'Class link updated',class_slot_cancel:'Class time cancelled',class_complete:'Class attendance recorded'};
function routeChoice(){return `<section class="path-choice-intro"><div><h2>Learn with a guide. Practise like a professional.</h2><p>Choose the format that fits your experience. Your weekly plan keeps one clear next step.</p></div>${link('Set my learning plan','plan',true)}</section><div class="path-choice-summary"><div>${icon('Book',24)}<h3>Guided Learning</h3><p>Start here if the skill is new. Follow a lesson, explain it in your own words, then build and check a small project.</p><span>6 steps · 10 projects per course</span></div><div>${icon('Briefcase',24)}<h3>Professional Practice</h3><p>Apply what you know to a realistic brief. Investigate failures, improve your work and prepare a complete handover.</p><span>12 stages · specialist missions</span></div></div>`}
async function home(c,base){ctx=c;if(c.mode!=='connected')return base+routeChoice();let data;try{data=await c.api('plan')}catch(err){if(err.status===401||err.status===403)throw err;return base+'<p class="notice">Your learning plan could not load. Your courses remain available; reopen My learning plan to try again.</p>'+routeChoice()}savedPlan=data.plan;const current=savedPlan?`<section class="saved-plan-strip"><div>${icon(savedPlan.mode==='Guided'?'Book':'Briefcase',24)}<b>${esc(savedPlan.mode==='Guided'?'Guided Learning':'Professional Practice')}</b><span>${esc(savedPlan.mode==='Guided'?c.track(savedPlan.course_id)?.title:data.programmes.find(p=>p.id===savedPlan.programme_id)?.title||savedPlan.programme_id)} · ${savedPlan.hours} hours / week</span></div><div class="row">${savedPlan.mode==='Guided'?link('Open my planned course','path/'+savedPlan.course_id,true):`<a class="btn primary" href="workspace.html?programme=${encodeURIComponent(savedPlan.programme_id)}">Continue professional practice ${icon('Arrow',16)}</a>`}${link('Adjust my plan','plan')}</div></section>`:'';return base.replace('<div class="course-grid enrolled-courses">',current+'<div class="course-grid enrolled-courses">')+routeChoice()}
async function plan(c){ctx=c;const data=c.mode==='connected'?await c.api('plan'):{plan:null,programmes:[]};savedPlan=data.plan;const p=data.plan,available=c.atlas.tracks.filter(c.allowed),mode=p?.mode||'Guided',zone=p?.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Kolkata';return `<div class="page-head"><div><h1>Your learning plan</h1><p>One route, one skill and a pace you can keep. Save it to your account and return on any device.</p></div>${link('My courses','home')}</div><form id="learning-plan-form" class="learning-plan-form"><fieldset class="route-options"><legend>Choose how you want to learn</legend><label class="route-option"><input type="radio" name="mode" value="Guided" ${mode==='Guided'?'checked':''}><div>${icon('Book',28)}<h2>Guided Learning</h2><p>For a new skill or a fresh start. Follow short explanations and small projects in order.</p><strong>Understand → explain → build → test → reflect → submit</strong></div></label><label class="route-option"><input type="radio" name="mode" value="Professional" ${mode==='Professional'?'checked':''}><div>${icon('Briefcase',28)}<h2>Professional Practice</h2><p>For applying a skill to a complete working brief. Investigate problems and defend your decisions.</p><strong>Brief → investigate → build → fix → verify → hand over</strong></div></label></fieldset><section class="plan-controls"><h2>Make it practical</h2><div class="two-col"><label class="field" data-plan-guided><span>Your guided course</span><select name="courseId">${available.map(t=>`<option value="${t.id}" ${p?.course_id===t.id?'selected':''}>${esc(t.title)}${t.free?' · Free':''}</option>`).join('')}</select></label><label class="field" data-plan-professional><span>Your professional programme</span><select name="programmeId">${data.programmes.map(t=>`<option value="${t.id}" ${p?.programme_id===t.id?'selected':''}>${esc(t.id+' · '+t.title)}</option>`).join('')}</select></label><label class="field"><span>Practice hours each week</span><input name="hours" type="number" min="1" max="40" value="${p?.hours||c.session?.user.hours||5}" required></label><label class="field"><span>Your timezone</span><select name="timezone">${[...new Set([zone,'Asia/Kolkata','Asia/Dubai','Europe/London','America/New_York','UTC'])].map(z=>`<option ${zone===z?'selected':''}>${esc(z)}</option>`).join('')}</select></label></div><fieldset class="practice-days"><legend>Choose your practice days</legend>${days.map((d,i)=>`<label><input name="days" type="checkbox" value="${i}" ${(p?JSON.parse(p.days):[1,3,5]).includes(i)?'checked':''}><span>${d.slice(0,3)}</span></label>`).join('')}</fieldset><p class="small muted">Your hours are a personal practice budget. The Academy does not promise completion in a fixed time. Paid teacher bundles have their own agreed class schedule.</p><div class="row"><button class="btn primary" ${c.mode==='connected'?'':'disabled'}>Save my weekly plan ${icon('Check',17)}</button><a class="btn" href="#calendar">Schedule a practice session</a></div><p class="form-status" role="status"></p></section></form><section class="plan-handbook"><h2>How to use your route</h2><div data-plan-guided><ol><li><b>Open your next project.</b> Read the outcome and the explanation before opening a tool.</li><li><b>Explain the idea.</b> Write or voice-type what you understood. Keep the example in your own words.</li><li><b>Build, test and improve.</b> Work in the recommended tool, test an ordinary case and a failure, then record what changed.</li><li><b>Keep your evidence.</b> Save your draft, complete the six steps and submit when ready. Assessment and certificates follow qualified review.</li></ol></div><div data-plan-professional><ol><li><b>Choose one mission.</b> Begin with the brief, boundaries and acceptance criteria.</li><li><b>Use the 12-stage rail.</b> Follow the stages in order. The workspace gives each stage its own instructions and evidence fields.</li><li><b>Investigate before fixing.</b> Use the tools, inspect the result, test a failure and explain your decision.</li><li><b>Prepare a handover.</b> Export your evidence and save a cloud snapshot in Reviews, records & payments. Submit for the applicable review.</li></ol></div><p><a href="#guide/professional">Read the complete Professional Practice guide</a> or <a href="#guide/recipes">see all six guided steps</a>.</p></section>`}
async function activity(c){ctx=c;const data=await c.api('activity');return `<div class="page-head"><div><h1>Your Academy activity</h1><p>Saved plans, submitted work, class bookings and confirmed payments from your account.</p></div>${link('Continue learning','home')}</div>${data.items.length?`<ol class="activity-records">${data.items.map(item=>`<li>${icon(item.action.startsWith('class_')?'Calendar':item.action==='payment_confirmed'?'Check':'Folder')}<div><b>${esc(labels[item.action]||item.action.replaceAll('_',' '))}</b><time datetime="${esc(item.created)}">${esc(date(item.created))}</time></div></li>`).join('')}</ol>`:`<section class="empty-state"><h2>Your first activity starts with a plan.</h2><p>Save a learning plan or work on your first project. Records appear here after you save them to the Academy.</p>${link('Set my plan','plan',true)}</section>`}<p class="muted small">Opening a lesson is not a completion or a grade. Your assessment record is available in <a href="#portfolio">My work & assessment</a>.</p>`}
function courses(c,selected=[],name='domains'){return `<div class="course-scope">${c.atlas.tracks.map(t=>`<label class="checkbox"><input type="checkbox" name="${name}" value="${t.id}" ${selected.includes(t.id)?'checked':''}><span>${esc(t.title)}</span></label>`).join('')}</div>`}
function accountRow(a,c){const active=a.status==='Active',teacher=a.kind==='Mentor';return `<details class="launch-person"><summary><span>${icon(a.kind==='Administrator'?'Shield':teacher?'People':'Compass')}<b>${a.kind==='Administrator'?'Administrator':a.kind==='Demo'?'Full learning demo':'Teacher '+a.id.split('-')[1]}</b><small>${esc(a.name||'Add this person’s details')}</small></span><span class="status ${active?'good':''}">${esc(a.status)}</span></summary>${a.kind==='Administrator'?'<p class="small">Your existing verified owner account is the administrator. Merchant connections and team appointments are available only to this account.</p>':a.user_id?`<p>${esc(a.name)} · ${esc(a.email)}</p><p class="small">Access ends ${esc(a.expires)}. ${teacher?'Course scope: '+JSON.parse(a.domains).map(x=>esc(c.track(x)?.title||x)).join(', '):'All guided courses and all professional programmes. Administrative records remain private.'}</p><form data-launch-action="revoke"><input type="hidden" name="slotId" value="${esc(a.id)}"><label class="field"><span>Reason for withdrawing this access</span><textarea name="reason" minlength="20" maxlength="2000" required></textarea></label><button class="btn">Withdraw appointment</button><p class="form-status" role="status"></p></form>`:`<form data-launch-action="account"><input type="hidden" name="slotId" value="${esc(a.id)}"><div class="two-col"><label class="field"><span>${teacher?'Teacher':'Demo learner'} name</span><input name="name" value="${esc(a.name)}" minlength="2" maxlength="120" required></label><label class="field"><span>Sign-in email</span><input name="email" type="email" value="${esc(a.email||'')}" autocomplete="off" required></label><label class="field"><span>Access expiry · within one year</span><input name="expires" type="date" value="${esc(a.expires||'')}" min="${new Date().toISOString().slice(0,10)}" max="${new Date(Date.now()+366*86400000).toISOString().slice(0,10)}" required></label></div>${teacher?`<fieldset><legend>Courses this teacher can teach</legend>${courses(c,JSON.parse(a.domains))}</fieldset><label class="field"><span>Checked qualifications and relevant teaching experience</span><textarea name="qualification" minlength="100" maxlength="10000" required>${esc(a.qualification)}</textarea></label><label class="checkbox"><input name="qualificationChecked" type="checkbox" required>I have checked this person’s qualifications for the assigned subjects.</label>`:'<p class="small">This account gets all learning courses, professional programmes and practice tools. It receives no access to other people’s payments or administrative records.</p>'}<button class="btn primary">Save ${teacher?'teacher':'demo'} appointment</button><p class="form-status" role="status"></p><p class="small muted">Share Academy access with this person, then ask them to sign in using this email and complete registration. This form records access; it does not send an invitation email.</p></form>`}</details>`}
function productForm(p,c){return `<form data-launch-action="product"><div class="two-col"><label class="field"><span>Offer ID</span><input name="id" value="${esc(p.id||'')}" pattern="[a-z0-9-]{3,80}" ${p.id?'readonly':''} placeholder="website-course" required></label><label class="field"><span>Offer title</span><input name="title" value="${esc(p.title||'')}" minlength="3" maxlength="160" required></label><label class="field"><span>Total checkout price · INR</span><input name="rupees" type="text" inputmode="decimal" value="${p.amount?(p.amount/100).toFixed(2):''}" pattern="[0-9]+(\.[0-9]{1,2})?" placeholder="Enter your approved price" required></label><label class="field"><span>Course access · days</span><input name="durationDays" type="number" min="1" max="3650" value="${p.durationDays||365}" required></label></div><fieldset><legend>Included courses</legend>${courses(c,p.courseIds||[],'courseIds')}</fieldset><label class="field"><span>Dedicated teaching bundle</span><select name="teacherCourseId"><option value="">Course access only</option>${c.atlas.tracks.map(t=>`<option value="${t.id}" ${p.teachingPlan?.courseId===t.id?'selected':''}>${esc(t.title)} · 8 weeks / 24 × 2-hour classes</option>`).join('')}</select></label><label class="field"><span>Purchase terms URL</span><input name="termsUrl" type="url" value="${esc(p.termsUrl||launch.merchant.business.termsUrl||'')}" placeholder="https://your-site.com/terms" required></label><label class="field"><span>Actual refund policy displayed before payment</span><textarea name="refundPolicy" minlength="20" maxlength="4000" required>${esc(p.refundPolicy||'')}</textarea></label><label class="field"><span>Offer status</span><select name="status"><option ${p.status!=='Live'?'selected':''}>Draft</option><option ${p.status==='Live'?'selected':''}>Live</option></select></label><label class="checkbox"><input name="approved" type="checkbox">I approve this actual INR price, included courses, teaching commitment and purchase terms.</label><button class="btn primary">Save offer</button><p class="form-status" role="status"></p><p class="small muted">Only approved Live offers with a connected live merchant can be purchased. A teacher bundle also needs a qualified teacher assigned to that course.</p></form>`}
async function operations(c){ctx=c;if(c.session?.user.role!=='Owner')throw Error('Only the Academy administrator can open launch settings.');await c.api('operations/initialize','POST',{});launch=await c.api('operations');const m=launch.merchant;return `<div class="page-head"><div><h1>Launch & team</h1><p>Connect your merchant, publish your actual offers and appoint your teaching team.</p></div><a class="btn" href="/admin">Learner administration ${icon('Shield',16)}</a></div><ol class="launch-flow"><li><button class="btn" data-launch-scroll="launch-business" type="button">1. Business</button></li><li><button class="btn" data-launch-scroll="launch-merchant" type="button">2. Payments</button></li><li><button class="btn" data-launch-scroll="launch-offers" type="button">3. Course offers</button></li><li><button class="btn" data-launch-scroll="launch-team" type="button">4. Team</button></li></ol><p class="notice">${esc(launch.sharing)}</p><div class="launch-summary"><span><b>${launch.counts.registered}</b> registered accounts</span><span><b>${launch.counts.paid}</b> confirmed purchases</span><span><b>${launch.counts.teachers}</b> active teachers</span><span><b>${launch.counts.waitingPackages}</b> packages awaiting a teacher</span></div><section id="launch-business" class="launch-section"><h2>1. Your business</h2><p>Students see your business name at checkout and can contact your support address.</p><form data-launch-action="business"><div class="two-col"><label class="field"><span>Business display name</span><input name="name" value="${esc(m.business.name||'')}" minlength="2" maxlength="120" required></label><label class="field"><span>Support email</span><input name="supportEmail" type="email" value="${esc(m.business.supportEmail||'')}" required></label></div><label class="field"><span>Purchase terms URL</span><input name="termsUrl" type="url" value="${esc(m.business.termsUrl||'')}" placeholder="https://your-site.com/terms" required></label><button class="btn primary">Save business details</button><p class="form-status" role="status"></p></form></section><section id="launch-merchant" class="launch-section"><div class="row between"><h2>2. Connect Razorpay</h2><span class="status ${m.razorpay.mode==='Live'?'good':''}">${esc(m.razorpay.mode)}</span></div>${!m.publicPaymentsReady?'<p class="notice">Live enrolment is paused. Finish your merchant settings and approved offers, check the public payment notification endpoint, then enable payments in your host environment.</p>':''}<p>INR checkout for cards, UPI, netbanking and eligible merchant wallets. Enter credentials here; keep them out of chat and lesson evidence.</p><form data-launch-action="merchant" autocomplete="off"><label class="field"><span>Merchant key ID${m.razorpay.configured?' · leave blank to keep the current key':''}</span><input name="keyId" autocomplete="off" placeholder="rzp_live_…" ${m.razorpay.configured?'':'required'}></label><div class="two-col"><label class="field"><span>Key secret</span><input name="keySecret" type="password" autocomplete="new-password" minlength="12" maxlength="200" ${m.razorpay.configured?'':'required'}></label><label class="field"><span>Webhook secret</span><input name="webhookSecret" type="password" autocomplete="new-password" minlength="16" maxlength="200" ${m.razorpay.configured?'':'required'}></label></div><button class="btn primary">Verify and save merchant connection</button><p class="form-status" role="status"></p></form><details class="launch-instructions"><summary>Set up the payment notifications</summary><p>In your Razorpay merchant dashboard, add the HTTPS webhook below with the same webhook secret. Subscribe to <b>payment.captured</b>, <b>order.paid</b> and <b>refund.processed</b>, <b>payment.dispute.created</b>, <b>payment.dispute.under_review</b> and <b>payment.dispute.lost</b>. Enable automatic capture for your merchant checkout.</p><code class="launch-webhook">${esc(location.origin+m.webhookPath)}</code><p>Use the merchant dashboard for refunds. The Academy checks authenticated provider records and withdraws course access after a full refund. Test-mode credentials are kept separate from student purchases.</p><a href="https://dashboard.razorpay.com/" target="_blank" rel="noopener noreferrer">Open Razorpay merchant dashboard ${icon('Arrow',16)}</a></details></section><section id="launch-offers" class="launch-section"><h2>3. Publish your course offers</h2><p>Enter your approved prices and inclusions. Students purchase only the courses listed in an offer.</p>${m.products.map(p=>`<details class="launch-offer"><summary><b>${esc(p.title||p.id)}</b><span>${esc(window.AcademyReceipt.money(p.amount,p.currency))} · ${esc(p.status)}</span></summary>${productForm(p,c)}</details>`).join('')}<details class="launch-offer"><summary><b>Add a course offer</b>${icon('Cart')}</summary>${productForm({},c)}</details></section><section id="launch-team" class="launch-section"><h2>4. Your administrator, demo and six teachers</h2><p>Each person uses their own verified sign-in. Teacher access follows the courses you assign.</p>${launch.accounts.map(a=>accountRow(a,c)).join('')}<div class="row launch-team-links">${link('Manage teacher packages & classes','teaching-staff',true)}${link('Open review workspace','staff')}</div><p class="small muted">Teacher appointments do not automatically appoint certificate reviewers or verifiers. Independent assessment roles are recorded separately in administration.</p></section>`}
function mount(c){ctx=c;document.querySelectorAll('[data-launch-scroll]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.launchScroll).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'}));document.querySelectorAll('.course-card').forEach(el=>{const id=el.dataset.course;el.dataset.palette=({start:'mint',safety:'mint',web:'coral',code:'coral',cloud:'blue',data:'blue',finance:'blue',logistics:'blue',ai:'violet',localai:'violet',automation:'violet',nocode:'coral',content:'amber',design:'amber',business:'mint',career:'violet',leadership:'mint',delivery:'coral',commerce:'amber'}[id]||'amber')});const f=document.getElementById('learning-plan-form');if(f){const switchMode=()=>{const guided=f.elements.mode.value==='Guided';document.querySelectorAll('[data-plan-guided]').forEach(el=>el.hidden=!guided);document.querySelectorAll('[data-plan-professional]').forEach(el=>el.hidden=guided)};f.querySelectorAll('[name=mode]').forEach(el=>el.onchange=switchMode);switchMode()}}
document.addEventListener('submit',async e=>{const form=e.target,action=form.dataset.launchAction;if(!ctx||(!action&&form.id!=='learning-plan-form'))return;e.preventDefault();const button=form.querySelector('button'),status=form.querySelector('.form-status'),fd=new FormData(form),b=Object.fromEntries(fd);button.disabled=true;status.classList.remove('has-error');status.textContent='Saving…';try{let response;if(form.id==='learning-plan-form'){b.hours=Number(b.hours);b.days=fd.getAll('days').map(Number);b.expectedRevision=savedPlan?.revision||0;response=await ctx.api('plan','PUT',b);status.textContent='Your weekly plan is saved. Open your course or professional mission to begin.';savedPlan={...savedPlan,revision:response.revision};const route=b.mode==='Guided'?'#path/'+b.courseId:'workspace.html?programme='+encodeURIComponent(b.programmeId);let next=form.querySelector('.plan-start-link');if(!next){next=document.createElement('a');next.className='btn primary plan-start-link';status.after(next)}next.href=route;next.textContent=b.mode==='Guided'?'Open my planned course':'Open my professional programme';return}let path='operations/'+action,method='PUT';if(action==='account'){b.domains=fd.getAll('domains');b.qualificationChecked=fd.has('qualificationChecked')}if(action==='revoke'){path='operations/account/revoke';method='POST'}if(action==='product'){if(!/^\d+(\.\d{1,2})?$/.test(b.rupees))throw Error('Enter an INR price with no more than two decimal places.');const [whole,fraction='']=b.rupees.split('.'),amount=Number(whole)*100+Number(fraction.padEnd(2,'0'));const product={...b,amount,currency:'INR',durationDays:Number(b.durationDays),courseIds:fd.getAll('courseIds'),approved:fd.has('approved')},others=launch.merchant.products.filter(p=>p.id!==b.id).map(p=>({...p,approved:!!p.reviewApproval,teacherCourseId:p.teachingPlan?.courseId||''}));path='operations/products';response=await ctx.api(path,method,{products:[...others,product]})}else response=await ctx.api(path,method,b);if(action==='merchant'){form.elements.keySecret.value='';form.elements.webhookSecret.value='';form.elements.keyId.value=''}status.textContent=response.message||'Saved successfully.';window.AcademyUI.toast(response.message||'Saved successfully.');if(action!=='merchant'){if(action==='product')Object.assign(ctx.session,await ctx.api('bootstrap'));await ctx.render();}else{const snapshot=await ctx.api('operations');launch=snapshot;form.closest('.launch-section').querySelector('.status').textContent=snapshot.merchant.razorpay.mode}}catch(err){status.textContent=err.message;status.classList.add('has-error')}finally{button.disabled=false}});
window.AcademyProduction={home,plan,activity,operations,mount};
})();
